mapper.select:
SELECT issue_id, source_table, source_key, issue_type, severity, message
  FROM migration_issue
 WHERE run_id = #{runId}

   AND severity = #{severity}

 ORDER BY issue_id
 LIMIT #{limit}

mapper.update:
